@push('scripts')<script>(()=>{const wrap=document.querySelector('.dj-search'),input=document.getElementById('headerSearchInput'),panel=document.getElementById('headerSearchPanel'),form=document.getElementById('headerSearchForm');if(!wrap||!input)return;const open=()=>wrap.classList.add('is-open'),close=()=>wrap.classList.remove('is-open');input.addEventListener('focus',open);input.addEventListener('click',open);document.addEventListener('click',e=>{if(!wrap.contains(e.target))close()});form?.addEventListener('submit',()=>{const q=input.value.trim();if(!q)return;try{const key='digitalshop_recent_searches';let a=JSON.parse(localStorage.getItem(key)||'[]');a=[q,...a.filter(x=>x!==q)].slice(0,8);localStorage.setItem(key,JSON.stringify(a))}catch(e){}});document.getElementById('clearRecentSearches')?.addEventListener('click',()=>{try{localStorage.removeItem('digitalshop_recent_searches')}catch(e){}document.getElementById('recentSearchChips').innerHTML='<span class="search-empty">جستجوهای اخیر پاک شد.</span>'});})();</script>@endpush